'withdrawn', v.withdrawn_at is not null) order by v.id)
from fat.rate_versions v join fat.rates r on r.id = v.rate_id where coalesce(((c2_plan->'target_scope')->>'has_source')::boolean, false) and r.code in ('enterprise_base_pay_weekly', 'overtime_rate_factor', 'overtime_hourly_divisor', 'double_time_multiplier', 'single_time_multiplier', 'time_and_half_multiplier', 'travel_per_km', 'meal_allowance', 'spoilt_meal_allowance', 'relieving_allowance')), '[]'::jsonb),
